// Command wordfreq prints the ten most frequent ASCII-letter words read from
// standard input, one "<count> <word>" line each.
package main

import (
	"bufio"
	"fmt"
	"os"
)

const topN = 10

func main() {
	counts, err := CountWords(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}

	w := bufio.NewWriter(os.Stdout)
	for _, e := range Top(counts, topN) {
		fmt.Fprintf(w, "%d %s\n", e.Count, e.Word)
	}
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

package main

import (
	"cmp"
	"errors"
	"io"
	"slices"
	"strings"
)

const readBufferSize = 64 << 10

// Entry is a word together with its number of occurrences.
type Entry struct {
	Word  string
	Count int
}

// CountWords reads r to EOF and returns the occurrence count of every word.
// A word is a maximal run of ASCII letters, folded to lowercase; every other
// byte is a separator.
func CountWords(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int)
	buf := make([]byte, readBufferSize)
	word := make([]byte, 0, 64)

	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if lower := b | 0x20; lower >= 'a' && lower <= 'z' {
				word = append(word, lower)
			} else if len(word) > 0 {
				counts[string(word)]++
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		counts[string(word)]++
	}
	return counts, nil
}

// Top returns at most limit entries ordered by count descending, with ties
// broken by word in ascending byte order.
func Top(counts map[string]int, limit int) []Entry {
	entries := make([]Entry, 0, len(counts))
	for w, c := range counts {
		entries = append(entries, Entry{Word: w, Count: c})
	}
	slices.SortFunc(entries, func(a, b Entry) int {
		if c := cmp.Compare(b.Count, a.Count); c != 0 {
			return c
		}
		return strings.Compare(a.Word, b.Word)
	})
	return entries[:min(limit, len(entries))]
}

package main

import (
	"slices"
	"strings"
	"testing"
)

func TestCountWords(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  map[string]int
	}{
		{"empty", "", map[string]int{}},
		{"case folding", "Hello, hello! HELLO? world.\n", map[string]int{"hello": 3, "world": 1}},
		{"separators", "don't stop_me 4now, now-NOW", map[string]int{"don": 1, "t": 1, "stop": 1, "me": 1, "now": 3}},
		{"non-ascii bytes", "caf\xc3\xa9\xff@[`{Z", map[string]int{"caf": 1, "z": 1}},
		{"trailing word", "abc", map[string]int{"abc": 1}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := CountWords(strings.NewReader(tt.input))
			if err != nil {
				t.Fatal(err)
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %v, want %v", got, tt.want)
			}
			for w, c := range tt.want {
				if got[w] != c {
					t.Errorf("count[%q] = %d, want %d", w, got[w], c)
				}
			}
		})
	}
}

func TestTop(t *testing.T) {
	counts := map[string]int{"the": 2, "cat": 1, "and": 1, "hat": 1}
	got := Top(counts, 10)
	want := []Entry{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}
	if !slices.Equal(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
	if got := Top(counts, 2); len(got) != 2 {
		t.Errorf("limit not applied: %v", got)
	}
}
